1	use std::collections::BTreeMap;
2	
3	use serde_json::{Value, json};
4	
5	use crate::config::Config;
6	
7	const SENSITIVE_VLLM_ENV_PATTERNS: &[&str] =
8	    &["KEY", "SECRET", "TOKEN", "PASSWORD", "CREDENTIAL", "AUTH"];
9	
10	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
11	pub(crate) enum ServerInfoConfigFormat {
12	    Text,
13	    Json,
14	}
15	
16	/// Snapshot returned by `/server_info`.
17	#[derive(Debug, Clone)]
18	pub(crate) struct ServerInfoSnapshot {
19	    vllm_config_text: String,
20	    vllm_config_json: Value,
21	    vllm_env: BTreeMap<String, String>,
22	    system_env: BTreeMap<String, String>,
23	}
24	
25	impl ServerInfoSnapshot {
26	    /// Capture the runtime configuration fields available to the Rust frontend.
27	    pub(crate) fn from_config(config: &Config) -> Self {
28	        let vllm_config_json =
29	            serde_json::to_value(config).expect("server info value must serialize");
30	
31	        Self {
32	            vllm_config_text: render_config_text(&vllm_config_json),
33	            vllm_config_json,
34	            vllm_env: collect_vllm_env(),
35	            system_env: collect_system_env(),
36	        }
37	    }
38	
39	    pub(crate) fn response(&self, config_format: ServerInfoConfigFormat) -> Value {
40	        let vllm_config = match config_format {
41	            ServerInfoConfigFormat::Text => Value::String(self.vllm_config_text.clone()),
42	            ServerInfoConfigFormat::Json => self.vllm_config_json.clone(),
43	        };
44	
45	        json!({
46	            "vllm_config": vllm_config,
47	            "vllm_env": self.vllm_env.clone(),
48	            "system_env": self.system_env.clone(),
49	        })
50	    }
51	}
52	
53	fn render_config_text(config: &Value) -> String {
54	    match config {
55	        Value::Object(fields) => fields
56	            .iter()
57	            .map(|(key, value)| format!("{key}={}", render_config_text_value(value)))
58	            .collect::<Vec<_>>()
59	            .join("\n"),
60	        _ => render_config_text_value(config),
61	    }
62	}
63	
64	fn render_config_text_value(value: &Value) -> String {
65	    match value {
66	        Value::Null => "None".to_string(),
67	        Value::String(value) => value.clone(),
68	        _ => value.to_string(),
69	    }
70	}
71	
72	fn collect_vllm_env() -> BTreeMap<String, String> {
73	    std::env::vars().filter(|(key, _)| is_public_vllm_env_key(key)).collect()
74	}
75	
76	fn is_public_vllm_env_key(key: &str) -> bool {
77	    let key = key.to_ascii_uppercase();
78	    key.starts_with("VLLM_")
79	        && !SENSITIVE_VLLM_ENV_PATTERNS.iter().any(|pattern| key.contains(pattern))
80	}
81	
82	fn collect_system_env() -> BTreeMap<String, String> {
83	    BTreeMap::from([
84	        ("arch".to_string(), std::env::consts::ARCH.to_string()),
85	        ("family".to_string(), std::env::consts::FAMILY.to_string()),
86	        ("os".to_string(), std::env::consts::OS.to_string()),
87	    ])
88	}
