91	mod tests {
92	    use std::collections::BTreeSet;
93	
94	    use serde_json::{Value, json};
95	
96	    use super::{is_public_vllm_env_key, render_config_text};
97	
98	    #[test]
99	    fn render_config_text_formats_config_snapshot() {
100	        let rendered = render_config_text(&json!({
101	            "model": "test-model",
102	            "served_model_name": ["served-model"],
103	            "chat_template": null,
104	            "enable_log_requests": true,
105	        }));
106	        let lines = rendered.lines().collect::<BTreeSet<_>>();
107	
108	        assert_eq!(
109	            lines,
110	            BTreeSet::from([
111	                "chat_template=None",
112	                "enable_log_requests=true",
113	                "model=test-model",
114	                "served_model_name=[\"served-model\"]",
115	            ])
116	        );
117	        assert_eq!(
118	            render_config_text(&Value::String("inline".to_string())),
119	            "inline"
120	        );
121	        assert_eq!(render_config_text(&Value::Null), "None");
122	    }
123	
124	    #[test]
125	    fn server_info_env_filter_excludes_sensitive_vllm_keys() {
126	        for key in [
127	            "VLLM_API_KEY",
128	            "VLLM_AUTH_TOKEN",
129	            "VLLM_SECRET",
130	            "VLLM_PASSWORD",
131	            "VLLM_CREDENTIAL_FILE",
132	            "vllm_token",
133	        ] {
134	            assert!(!is_public_vllm_env_key(key), "{key}");
135	        }
136	    }
137	
138	    #[test]
139	    fn server_info_env_filter_includes_public_vllm_keys() {
140	        assert!(is_public_vllm_env_key("VLLM_LOGGING_LEVEL"));
141	        assert!(is_public_vllm_env_key("VLLM_USE_MODELSCOPE"));
142	        assert!(!is_public_vllm_env_key("OTHER_ENV"));
143	    }
144	}
