/// Debug helper that renders API keys as `[<redacted>; N]` (or `[]` when empty)
/// so that key material never reaches logs or debug snapshots.
struct RedactedApiKeys<'a>(&'a [String]);

impl fmt::Debug for RedactedApiKeys<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.0.is_empty() {
            write!(f, "[]")
        } else {
            write!(f, "[<redacted>; {}]", self.0.len())
        }
    }
}

/// Serialize API keys without leaking their values, preserving the list length
/// so serialized configuration snapshots (e.g. `/server_info`) show how many
/// keys are configured but never the keys themselves.
fn serialize_redacted_api_keys<S>(api_keys: &[String], serializer: S) -> Result<S::Ok, S::Error>
where
