/// Path prefixes that require a valid API key when authentication is enabled.
///
/// Covers the inference and model-listing surface (`/v1`, `/v2`) as well as the
/// vLLM-specific `/inference` endpoints. Routes outside these prefixes (such as
/// `/health`, `/metrics`, `/version`, and `/load`) are always served without
/// authentication.
const GUARDED_PREFIXES: &[&str] = &["/v1", "/v2", "/inference"];

/// Enforce bearer-token authentication on guarded routes.
///
/// Requests to a guarded prefix must carry an `Authorization: Bearer <key>`
/// header whose key matches one of the configured API keys; otherwise the
/// request is rejected with `401 Unauthorized` and a `{"error": "Unauthorized"}`
/// body. `OPTIONS` requests (e.g. CORS preflight) and requests to unguarded
/// routes bypass the check.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    // Preflight requests never carry credentials and must be allowed through.
    if req.method() == Method::OPTIONS {
        return next.run(req).await;
    }

    if !is_guarded(req.uri().path()) {
        return next.run(req).await;
    }

    if is_authorized(&req, state.api_keys()) {
        next.run(req).await
    } else {
        (StatusCode::UNAUTHORIZED, Json(json!({ "error": "Unauthorized" }))).into_response()
    }
}

/// Whether the given request path falls under a guarded prefix.
fn is_guarded(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| {
        path == *prefix || path.strip_prefix(prefix).is_some_and(|rest| rest.starts_with('/'))
    })
}

/// Whether the request presents a valid `Authorization: Bearer <key>` header
/// matching one of the configured API keys.
fn is_authorized(req: &Request, api_keys: &[String]) -> bool {
    let Some(token) = bearer_token(req) else {
        return false;
    };
    api_keys.iter().any(|key| key == token)
}

/// Extract the bearer token from the request's `Authorization` header, if any.
fn bearer_token(req: &Request) -> Option<&str> {
    req.headers()
        .get(header::AUTHORIZATION)?
        .to_str()
        .ok()?
        .strip_prefix("Bearer ")
        .map(str::trim)
}
